const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const el=id=>document.getElementById(id), main=el('main'),audio=el('audio'),playerEl=el('player'),dialog=el('dialog');
const oldState=readState();
let state={lastRead:oldState.lastRead||null,bookmarks:Array.isArray(oldState.bookmarks)?oldState.bookmarks:[],settings:{fontSize:34,dark:false,tajweed:false,latin:true,translation:true,readingMode:'ayah',reciter:123,...oldState.settings}};
state.settings.fontSize=Math.min(48,Math.max(24,Number(state.settings.fontSize)||34));
let selectedPageAyah=null;
let data,reciters=[],surahs=[],downloaded=new Set(),view='home',search='',deferredInstall,offlineReady=false;
const downloads=new Map();let batch=false,batchAbort=false,toastTimer;
let player=null,playSeq=0,currentObjectURL=null,currentSource=null;
const meanings={1:'Pembuka',2:'Sapi Betina',3:'Keluarga Imran',4:'Wanita',5:'Hidangan',6:'Binatang Ternak',7:'Tempat Tertinggi',8:'Rampasan Perang',9:'Pengampunan',10:'Yunus',11:'Hud',12:'Yusuf',18:'Gua',36:'Yasin',55:'Yang Maha Pengasih',67:'Kerajaan',112:'Ikhlas',113:'Waktu Subuh',114:'Manusia'};
const hydrate=()=>document.querySelectorAll('[data-icon]').forEach(n=>n.innerHTML=icon(n.dataset.icon));
const reciterBy=(id=state.settings.reciter)=>reciters.find(r=>r.id===id)||reciters[0];
const downloadKey=(id,reciter=state.settings.reciter)=>reciter+':'+id;
const audioTiming=(id,n,reciter=player?.reciter||state.settings.reciter)=>reciterBy(reciter).chapters.find(s=>s.id===id).timings[n-1];
function applyReciter(){for(const s of surahs)s.audioBytes=reciterBy().chapters.find(c=>c.id===s.id).bytes;}
function reciterSelect(id='qari-select'){return `<label class="qari-choice" for="${id}"><span>Pilih qari</span><select id="${id}" class="reciter-select">${reciters.map(r=>`<option value="${r.id}" ${r.id===state.settings.reciter?'selected':''}>${esc(r.name)}${r.id===123?' · bawaan':''}</option>`).join('')}</select><small>114 surah · Riwayat Hafs</small></label>`;}
function renderAudioChoice(){if(el('audio-choice'))el('audio-choice').innerHTML=reciterSelect();}
function stopPlayer(){++playSeq;audio.pause();audio.removeAttribute('src');audio.load();if(currentObjectURL)URL.revokeObjectURL(currentObjectURL);currentObjectURL=null;currentSource=null;player=null;renderPlayer();markPlaying();}
let reciterChange=0;
async function changeReciter(id){if(id===state.settings.reciter||!reciters.some(r=>r.id===id))return;const token=++reciterChange,position=player?{surah:player.surah,ayah:player.ayah,continuous:player.continuous,scope:player.scope}:currentRoute(),wasPlaying=Boolean(player&&!audio.paused),panel=dialog.dataset.panel;stopPlayer();state.settings.reciter=id;applyReciter();persist();downloaded=new Set();try{const keys=await listAudio(id);if(token!==reciterChange)return;downloaded=new Set(keys);}catch{toast('Penyimpanan audio tidak tersedia.');}if(token!==reciterChange)return;render();if(panel==='audio')showAudioPanel(position);if(wasPlaying&&position)await playAyah(position.surah,position.ayah,position.continuous,position.scope);}
const sBy=id=>surahs.find(s=>s.id===Number(id));
function toast(message){el('toast').textContent=message;el('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el('toast').classList.remove('visible'),3500)}
function persist(){try{writeState(state);return true}catch{toast('Penyimpanan penuh atau tidak tersedia. Perubahan belum tersimpan.');return false}}
function applySettings(){document.body.classList.toggle('dark',Boolean(state.settings.dark));document.documentElement.style.setProperty('--arabic-size',state.settings.fontSize+'px')}
function setConnection(){const n=el('connection');if(!n)return;n.classList.toggle('pending',!offlineReady);n.innerHTML=`<i></i>${offlineReady?(navigator.onLine?'Teks siap offline':'Mode offline'):(navigator.onLine?'Menyiapkan offline':'Teks belum tersimpan')}`;}
function navigate(hash){selectedPageAyah=null;if(location.hash===hash)render();else location.hash=hash;}
function currentRoute(){const r=parseRoute(location.hash,surahs,data?.pages);if(r)r.mode=r.page?'page':location.hash.startsWith('#surah/')?'surah':'ayah';return r;}
function readingLink(id,ayah=1,mode=state.settings.readingMode){return mode==='page'?'#page/'+pageForPosition(data.pages,id,ayah)+'/'+id+'/'+ayah:(mode==='surah'?'#surah/':'#read/')+id+'/'+ayah;}
function goRead(id,ayah=1,mode=state.settings.readingMode){state.settings.readingMode=mode;persist();navigate(readingLink(id,ayah,mode));}
function goPage(page){if(page>=1&&page<=604){state.settings.readingMode='page';persist();navigate('#page/'+page);scrollTo(0,0);}}
function currentPosition(){const r=currentRoute();if(!r||r.page)return r;const visible=[...document.querySelectorAll('.ayah')].find(n=>n.getBoundingClientRect().bottom>(document.querySelector(".reader-sticky")?.getBoundingClientRect().bottom||0)+24);return visible?{surah:Number(visible.dataset.surah),ayah:Number(visible.dataset.ayah)}:r;}
function setNav(name){document.querySelectorAll('[data-nav]').forEach(n=>{if(n.dataset.nav===name)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current')})}
function dateMarkup(){const now=new Date();return `<div class="date"><strong>${esc(new Intl.DateTimeFormat('id-ID',{weekday:'long',day:'numeric',month:'short'}).format(now))}</strong>${esc(new Intl.DateTimeFormat('id-ID-u-ca-islamic',{day:'numeric',month:'long',year:'numeric'}).format(now))}</div>`;}
const art=`<svg viewBox="0 0 330 235" xmlns="http://www.w3.org/2000/svg"><defs><pattern id="stars" width="54" height="54" patternUnits="userSpaceOnUse"><path d="m27 1 7 17 18 9-18 7-7 19-8-19L1 27l18-9Z" fill="none" stroke="#d5dda8" stroke-width=".5" opacity=".26"/></pattern></defs><rect width="330" height="235" fill="url(#stars)"/><path d="m110 172 57-45 72 45-68 33Z" fill="#102e26" opacity=".5"/><path d="m125 201 89-75m-67 0 88 75" stroke="#b79d63" stroke-width="8" stroke-linecap="round"/><path d="M169 166c-17-24-42-38-76-39l23-71c28 2 48 16 65 43l18 66Z" fill="#e9ddba"/><path d="M169 166c24-12 51-15 81-9l21-71c-30-7-60-4-90 13Z" fill="#f3e8c9"/><path d="m169 166 12-67" stroke="#ad996b" stroke-width="2"/><path d="m116 69 57 36m-61-22 58 35m-63-20 60 33m-64-19 61 32m27-36 65-14m-67 27 64-14m-67 27 63-13m-65 25 60-12" stroke="#b8a578" stroke-width="2" opacity=".65"/><path d="m98 130 70 41 86-10" stroke="#d1bb86" fill="none" stroke-width="4" stroke-linecap="round"/><path d="m278 39 3 8 8 3-8 3-3 8-3-8-8-3 8-3Z" fill="#dbc797" opacity=".75"/></svg>`;
function renderHome(){
  search='';
  const last=state.lastRead,s=sBy(last?.surah||1),juzMode=state.settings.readingMode==='page'?'page':'ayah';
  main.innerHTML=`<div class="home-heading"><h1>Al-Qur’an</h1><p>114 surah · 30 juz</p><div class="home-heading-actions"><button class="home-action" data-action="install" aria-label="Pasang Aplikasi">${icon('download')}<span>Pasang Aplikasi</span></button><button class="home-action" data-action="audio-panel" aria-label="Dengarkan Audio">${icon('headphones')}<span>Dengarkan Audio</span></button></div></div>
  <button class="resume-reading" data-action="continue" aria-label="${last?'Lanjutkan membaca':'Baca Al-Fatihah'}"><span class="resume-icon">${icon(last?'bookmark':'book')}</span><span><small>${last?'LANJUTKAN MEMBACA':'MULAI MEMBACA'}</small><strong>${esc(s.name)} <span>· Ayat ${last?.ayah||1}</span></strong></span>${icon('arrow')}</button>
  <nav class="reading-shortcuts" aria-label="Pilih cara membaca"><a href="${readingLink(s.id,last?.ayah||1,'page')}" aria-label="Qur’an Per Halaman"><span class="shortcut-icon"><img src="./icons/reading-page.png" width="32" height="32" alt="" decoding="async"></span><span>Qur’an<strong>Per Halaman</strong></span></a><a href="${readingLink(s.id,last?.ayah||1,'ayah')}" aria-label="Qur’an Per Ayat"><span class="shortcut-icon"><img src="./icons/reading-ayah.png" width="32" height="32" alt="" decoding="async"></span><span>Qur’an<strong>Per Ayat</strong></span></a><a href="#surahs" aria-label="Surah"><span class="shortcut-icon"><img src="./icons/reading-surah.png" width="32" height="32" alt="" decoding="async"></span><span>Daftar<strong>Surah</strong></span></a></nav>
  <section class="home-library" aria-label="Daftar Juz"><div class="list-toolbar"><h2>Juz</h2><span class="list-meta">30 juz</span></div><div class="surah-grid">${data.juzs.map(j=>`<a class="surah-card juz-card" href="${readingLink(j.surah,j.ayah,juzMode)}"><span class="number">${j.id}</span><div class="surah-info"><h3>Juz ${j.id}</h3><p>Mulai ${esc(sBy(j.surah).name)} · Ayat ${j.ayah}</p></div><span class="surah-arabic">${icon('arrow')}</span></a>`).join('')}</div><div class="section-foot">${icon('shield')}Teks Tanzil · Riwayat Hafs</div></section><div class="home-install"><button class="pill" data-action="install">${icon('download')}Pasang di layar utama</button></div>`;
  setConnection();
}
function surahCards(found){return found.map(s=>`<a class="surah-card" href="#surah/${s.id}/1"><span class="number">${s.id}</span><div class="surah-info"><h3>${esc(s.name)}</h3><p>${esc(s.meaning||meanings[s.id]||s.english)}<span>·</span>${s.count} ayat</p></div><span class="surah-arabic"><b lang="ar" dir="rtl">${esc(s.arabic)}</b><small>${s.type==='Meccan'?'Makkiyah':'Madaniyah'}</small></span></a>`).join('')||'<div class="empty"><h2>Surah belum ditemukan</h2><p>Coba nama lain atau nomor 1–114.</p></div>';}
function renderSurahDirectory(){main.innerHTML=`<section class="reader-shell surah-directory"><div class="reader-sticky"><div class="reader-bar"><a class="icon-btn" href="#home" aria-label="Kembali ke beranda">${icon('back')}</a><h1>Surah</h1><div class="reader-tools"><button class="icon-btn" data-action="audio-panel" aria-label="Buka pemutar audio">${icon('headphones')}</button><button class="icon-btn" data-action="settings" aria-label="Pengaturan bacaan">${icon('sliders')}</button></div></div><div class="reader-playback-bar" role="group" aria-label="Pilihan audio"><button class="reader-play-context" data-action="audio-panel" aria-label="Dengarkan Audio">${icon('play')}<span>Dengarkan Audio</span></button></div></div><div class="directory-content"><label class="search directory-search">${icon('search')}<input id="directory-search" type="search" autocomplete="off" placeholder="Cari nama atau nomor surah…" aria-label="Cari surah" value="${esc(search)}"></label><p class="search-count" id="list-count" role="status"></p><div id="surah-list" class="surah-grid"></div></div></section>`;renderList();}
function renderList(){const node=el('surah-list');if(!node)return;const found=findSurahs(surahs,search);node.innerHTML=surahCards(found);el('list-count').textContent=`${found.length} surah${search?' ditemukan':''}`;}
function closeHeaderSearch(clear=false){el('header-search-results').hidden=true;if(clear){el('header-search').value='';search='';}}
function updateHeaderSearch(){const q=el('header-search').value.trim(),results=el('header-search-results');if(!surahs.length){results.hidden=true;return;}if(view==='surahs'){search=q;renderList();results.hidden=true;return;}const found=findSurahs(surahs,q);results.innerHTML=`<p class="search-count" role="status">${found.length} surah${q?' ditemukan':''}</p><div class="search-results">${surahCards(found)}</div>`;results.hidden=false;}
function centerReaderNavigation(){const rail=document.querySelector('.reader-strip'),active=rail?.querySelector('[aria-current]');if(rail&&active){const a=active.getBoundingClientRect(),r=rail.getBoundingClientRect();rail.scrollLeft+=a.left-r.left-(r.width-a.width)/2;}}
function renderReader(route){
  disposePageViewer(route.page);
  main.innerHTML=readerHTML({data,surahs,route,settings:state.settings,lastRead:state.lastRead,bookmarks:state.bookmarks,player,downloaded,icon});
  centerReaderNavigation();
  const shell=document.querySelector(".reader-shell");shell.style.setProperty("--reader-header-height",shell.querySelector(".reader-sticky").offsetHeight+"px");
  syncAudioPanel();
  paintTajweed(surahs,state.settings.tajweed);
  if(route.page)mountPageViewer(route.page,goPage,()=>{
    document.querySelectorAll('.page-ayah').forEach(n=>{const id=Number(n.dataset.surah),ayah=Number(n.dataset.ayah),selected=selectedPageAyah?.page===route.page&&selectedPageAyah.surah===id&&selectedPageAyah.ayah===ayah;n.classList.toggle('selected',selected);n.classList.toggle('saved',state.lastRead?.surah===id&&state.lastRead.ayah===ayah);n.setAttribute('aria-pressed',String(selected));n.setAttribute('aria-label',sBy(id).name+', ayat '+ayah+'. Ketuk untuk dengarkan atau tandai.');});markPlaying();
  });
  else markPlaying();
  const token=location.hash;
  if(!route.page&&route.ayah>1)document.fonts.ready.then(()=>requestAnimationFrame(()=>{if(location.hash===token)el('ayah-'+route.ayah)?.scrollIntoView({block:'start',behavior:'instant'});}));

}
function renderBookmarks(){main.innerHTML=`<div class="section-heading"><div class="eyebrow">AYAT YANG INGIN KAMU KEMBALI BACA</div><h2>Penandamu</h2><p>Disimpan di perangkat ini, menemanimu tanpa koneksi.</p></div><div class="bookmark-list">${state.bookmarks.length?state.bookmarks.map(b=>`<div class="bookmark-item"><a href="${readingLink(b.surah,b.ayah)}">${esc(sBy(b.surah).name)} · Ayat ${b.ayah}<small>${esc(sBy(b.surah).ayahs[b.ayah-1].text.slice(0,65))}…</small></a><button class="icon-btn" data-action="bookmark" data-surah="${b.surah}" data-ayah="${b.ayah}" aria-label="Hapus penanda ${esc(sBy(b.surah).name)} ayat ${b.ayah}">${icon('trash')}</button></div>`).join(''):`<div class="empty">${icon('bookmark')}<h2>Simpan ayat yang berkesan.</h2><p>Ketuk ikon penanda pada ayat saat membaca. Kamu bisa kembali ke sini kapan saja.</p><a class="primary" href="#read/1/1">Mulai membaca ${icon('arrow')}</a></div>`}</div>`;}
function renderDownloads(){const bytes=surahs.filter(s=>downloaded.has(s.id)).reduce((n,s)=>n+s.audioBytes,0);main.innerHTML=`<div class="section-top"><div class="section-heading"><div class="eyebrow">BAWA KETENANGAN KE MANA SAJA</div><h2>Unduhan</h2><p>Murattal ${esc(reciterBy().name)} · Hafs</p></div><button class="pill" data-action="${batch?'cancel-all':'download-all'}">${icon(batch?'close':'download')}${batch?'Hentikan antrean':'Unduh semua · '+bytesLabel(surahs.reduce((n,s)=>n+s.audioBytes,0))}</button></div><section id="mushaf-download" class="mushaf-download" aria-label="Unduhan mushaf"></section>${reciterSelect('download-qari')}<div class="download-summary"><div class="stat-box"><b>${downloaded.size}<small> / 114</small></b><span>Surah tersimpan</span></div><div class="stat-box"><b>${bytesLabel(bytes)}</b><span>Penyimpanan audio</span></div></div><p class="download-info"><strong>Teks Per Ayat seluruh surah disimpan otomatis.</strong> Unduh audio pilihanmu untuk mendengarkan tanpa internet. Biarkan aplikasi terbuka selama unduhan; gunakan Wi-Fi untuk seluruh murattal. Browser dapat menghapus data jika ruang perangkat menipis.</p><div class="download-list">${surahs.map(s=>{const dl=downloads.get(downloadKey(s.id)),ready=downloaded.has(s.id);return `<div class="download-item"><span class="number">${s.id}</span><div><strong>${esc(s.name)}</strong><small>${dl?`Mengunduh ${Math.round(dl.progress*100)}%`:ready?'Siap didengarkan offline':`${s.count} ayat · ${bytesLabel(s.audioBytes)}`}</small>${dl?`<div class="download-progress"><span style="width:${dl.progress*100}%"></span></div>`:''}</div><button class="pill" data-action="${dl?'cancel-download':ready?'remove-audio':'download'}" data-surah="${s.id}" aria-label="${dl?'Batalkan unduhan':ready?'Hapus audio':'Unduh audio'} ${esc(s.name)}">${icon(dl?'close':ready?'trash':'download')}<span>${dl?'Batal':ready?'Hapus':'Unduh'}</span></button></div>`}).join('')}</div>`;refreshMushafDownloads();}
function render(){if(!data)return;const route=currentRoute();if(route&&state.settings.readingMode!==route.mode){state.settings.readingMode=route.mode;persist();}view=route?'read':location.hash==='#bookmarks'?'bookmarks':location.hash==='#downloads'?'downloads':location.hash==='#surahs'?'surahs':'home';document.body.classList.toggle('reading',view==='read'||view==='surahs');document.body.classList.toggle('page-reading',Boolean(route?.page));if(view!=='read'){disposePageViewer();paintTajweed(surahs,false);}setNav(view==='read'||view==='surahs'?'home':view);el('breadcrumb').innerHTML=`Al-Qur’an <span>/</span> ${route?esc(sBy(route.surah).name):({home:'Jelajahi',surahs:'Surah',bookmarks:'Penanda',downloads:'Unduhan'})[view]}`;document.title=route?`${sBy(route.surah).name} — Ayat`:'Ayat — Al-Qur’an, dekat denganmu';if(view==='read')renderReader(route);else if(view==='bookmarks')renderBookmarks();else if(view==='downloads')renderDownloads();else if(view==='surahs')renderSurahDirectory();else renderHome();hydrate();}
function dialogOpen(title,body){if(playerEl.parentElement!==document.body)document.body.append(playerEl);dialog.dataset.panel='';el('dialog-body').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Tutup">${icon('close')}</button></div>${body}`;if(!dialog.open)dialog.showModal();}
function showAyahActions(id,n){const marked=state.bookmarks.some(b=>b.surah===id&&b.ayah===n),saved=state.lastRead?.surah===id&&state.lastRead.ayah===n;dialogOpen(esc(sBy(id).name)+' · Ayat '+n,`<div class="verse-actions"><button data-action="play-ayah" data-surah="${id}" data-ayah="${n}">${icon('play')}Dengarkan ayat</button><button data-action="bookmark" data-surah="${id}" data-ayah="${n}" aria-pressed="${marked}">${icon('bookmark')}${marked?'Hapus penanda':'Simpan penanda'}</button><button data-action="save-position" data-surah="${id}" data-ayah="${n}" aria-pressed="${saved}">${icon(saved?'check':'clock')}${saved?'Batalkan':'Simpan'} posisi terakhir</button></div>`);dialog.dataset.panel='verse';syncPlaybackButtons();}
function showAudioPanel(position){const r=position||player||currentRoute()||state.lastRead||{surah:1,ayah:1};dialogOpen('Dengarkan Al-Qur’an',`<div id="audio-choice"></div><p class="audio-panel-caption">${esc(sBy(r.surah).name)} · Ayat ${r.ayah}</p><button class="primary audio-start" data-action="play-sequence" data-surah="${r.surah}" data-ayah="${r.ayah}">${icon('play')}Dengarkan mulai ayat ini</button><div class="audio-scope-options"><button data-action="play-scope" data-kind="surah" data-scope-id="${r.surah}">${icon('play')}Putar Surah ${esc(sBy(r.surah).name)}</button><button data-action="play-scope" data-kind="juz" data-scope-id="${juzAt(r)}">${icon('play')}Putar Juz ${juzAt(r)}</button></div><div id="audio-panel-player"></div><p class="dialog-copy">Audio tetap berjalan saat panel ditutup.</p>`);dialog.dataset.panel='audio';renderAudioChoice();renderPlayer();}
function syncAudioPanel(){document.querySelectorAll('[data-action="audio-panel"]').forEach(b=>{b.classList.toggle('audio-playing',Boolean(player&&!audio.paused));b.title=player&&!audio.paused?'Audio sedang diputar — buka kontrol':'Buka pemutar audio';});if(dialog.open&&dialog.dataset.panel==='audio'){if(player)el('audio-panel-player').append(playerEl);const start=dialog.querySelector('.audio-start');if(start)start.hidden=Boolean(player);}}
function showSettings(){dialogOpen('Ruang baca yang nyaman',`${currentRoute()?`<div class="setting-row"><label for="jump-ayah">Lompat ke ayat</label><select id="jump-ayah">${sBy(currentRoute().surah).ayahs.map(a=>`<option value="${a.n}" ${a.n===currentRoute().ayah?'selected':''}>Ayat ${a.n}</option>`).join('')}</select></div>`:''}<div class="setting-row"><span><strong>Ukuran teks Arab</strong><small>Per Ayat; gunakan zoom untuk Per Halaman.</small><small id="font-label">${state.settings.fontSize} px</small></span><input id="font-size" type="range" min="24" max="48" step="2" value="${state.settings.fontSize}" aria-label="Ukuran teks Arab"></div><div class="settings-example" lang="ar" dir="rtl">${esc(sBy(1).ayahs[0].text)}</div><div class="setting-row"><span><strong>Bacaan latin</strong><small>Tampilkan transliterasi di bawah setiap ayat.</small></span><button class="switch" role="switch" aria-label="Bacaan latin" aria-checked="${Boolean(state.settings.latin)}" data-action="latin"></button></div><div class="setting-row"><span><strong>Arti bahasa Indonesia</strong><small>Terjemahan di mode Per Ayat.</small></span><button class="switch" role="switch" aria-label="Arti bahasa Indonesia" aria-checked="${Boolean(state.settings.translation)}" data-action="translation"></button></div><div class="setting-row"><span><strong>Mode malam</strong><small>Tampilan lembut untuk membaca malam hari.</small></span><button class="switch" role="switch" aria-label="Mode malam" aria-checked="${Boolean(state.settings.dark)}" data-action="dark"></button></div><div class="setting-row"><span><strong>Tajwid warna · pratinjau</strong><small>Per Ayat · ${data.provenance.alignedAyahs.toLocaleString('id-ID')} ayat · belum ditashih independen.</small></span><button class="switch" role="switch" aria-label="Tajwid warna pratinjau" aria-checked="${Boolean(state.settings.tajweed)}" data-action="tajweed"></button></div><div class="setting-row"><span><strong>Cadangkan penanda</strong><small>Posisi terakhir dan penanda tersimpan lokal.</small></span><button class="pill" data-action="export">${icon('download')}Ekspor</button></div><div class="setting-row"><span><strong>Pulihkan penanda</strong><small>Gunakan berkas cadangan dari Ayat.</small></span><label class="pill" style="cursor:pointer">${icon('upload')}Impor<input id="import-file" type="file" accept="application/json,.json" hidden></label></div>${currentRoute()?`<div class="setting-row"><span><strong>Audio ${esc(sBy(currentRoute().surah).name)}</strong><small>Unduh hanya jika ingin mendengarkan offline.</small></span><button class="pill" id="reader-download" data-action="download" data-surah="${currentRoute().surah}">${downloaded.has(currentRoute().surah)?'Audio tersimpan':'Unduh audio'}</button></div>`:''}<div class="setting-row"><span><strong>Mushaf offline</strong><small>Simpan 604 halaman cetak di perangkat ini.</small></span><button class="pill" data-action="mushaf-downloads">Buka unduhan</button></div><div class="dialog-copy"><p>Pengaturan dan penanda tidak dikirim ke server.</p><button class="pill" data-action="sources">Sumber & lisensi</button></div>`)}
function showSources(){dialogOpen('Sumber & tentang Ayat',`<div class="dialog-copy"><p>Ayat adalah prototipe pembaca Al-Qur’an untuk Android, iPhone, dan desktop. Teks Arab lengkap, bacaan Latin, dan arti bahasa Indonesia. Pilih Per Ayat atau Per Halaman (pembagian 604 halaman, satu lembar utuh dengan zoom).</p><h3>Teks Al-Qur’an</h3><p>Tanzil Quran Text, Uthmani versi 1.1, riwayat Hafs. Teks disimpan tanpa perubahan. Copyright © 2007–2021 Tanzil Project. <a href="https://tanzil.net" target="_blank" rel="noopener">Tanzil Project</a> · <a href="./licenses/Tanzil.txt" target="_blank">Pemberitahuan lisensi lengkap</a>.</p><h3>Mushaf per halaman</h3><p>Halaman vektor Mushaf Al-Madinah, Hafs, edisi 1441 H, dari King Fahd Quran Complex melalui <a href="https://github.com/quran-ws/quran-svg" target="_blank" rel="noopener">Quran.ws / Quran SVG</a>. Bentuk tulisan, susunan baris, dan posisi ayat dipertahankan dari sumber; bingkai dan navigasi milik aplikasi. Pemetaan 604 halaman memuat 6.236 ayat lengkap. <a href="./licenses/Quran-SVG-NOTICE.txt" target="_blank">Izin penggunaan</a> · <a href="./licenses/Quran-SVG-LICENSE.txt" target="_blank">Lisensi</a> · <a href="./licenses/Quran-SVG-PROVENANCE.txt" target="_blank">Asal berkas</a>.</p><p>Lembar yang dibuka tersimpan otomatis. Paket lengkap tersedia di Unduhan. Berkas vektor menampilkan warna asli sumber; pratinjau tajwid warna berlaku pada mode Per Ayat.</p><h3>Arti, bacaan latin & nama surah</h3><p>Dari <a href="https://equran.id" target="_blank" rel="noopener">EQuran.id</a>, yang mencantumkan Kementerian Agama RI sebagai sumber datanya. Bacaan latin adalah bantuan, bukan pengganti teks Arab dan bimbingan pelafalan. <a href="./licenses/Indonesian.txt" target="_blank">Sumber dan ketentuan penggunaan</a>.</p><h3>Tajwid warna — pratinjau</h3><p>Anotasi oleh Collin Fair, <a href="https://github.com/cpfair/quran-tajweed" target="_blank" rel="noopener">cpfair/quran-tajweed</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>. Hanya ayat dengan teks yang cocok persis terhadap sumber anotasi yang diberi warna (${data.provenance.alignedAyahs.toLocaleString('id-ID')}/6.236). Anotasi lainnya tidak ditampilkan; aturan dan posisi tidak ditulis ulang.</p><p>Proyek sumber tidak aktif dipelihara. Warna pada prototipe ini belum ditashih secara independen dan tidak mencakup semua hukum tajwid. Pemeriksaan ahli masih diperlukan sebelum rilis umum.</p><h3>Audio</h3><p>${reciters.map(r=>esc(r.name)).join(', ')}, Hafs an Asim. Audio dan penanda waktu berasal dari <a href="https://mp3quran.net" target="_blank" rel="noopener">MP3Quran</a>, rekaman ${reciters.map(r=>r.id).join(', ')}. <a href="https://mp3quran.net/eng/privacy" target="_blank" rel="noopener">Izin publik penyedia</a> memperbolehkan penyalinan materi. Belum ada perjanjian hak khusus rekaman dari qari untuk prototipe ini.</p><p>114 surah dan 6.236 penanda ayat telah diperiksa secara struktural. Ketepatan seluruh batas audio belum diperiksa melalui pendengaran.</p><h3>Font & penyimpanan</h3><p>Scheherazade New, Amiri Quran, dan Plus Jakarta Sans — SIL Open Font License 1.1. <a href="./licenses/scheherazade-OFL.txt" target="_blank">Lisensi Scheherazade</a>. <a href="./licenses/amiriquran-OFL.txt" target="_blank">Lisensi Amiri</a> · <a href="./licenses/plusjakartasans-OFL.txt" target="_blank">Lisensi Jakarta</a>.</p><p>Penanda berada di perangkat ini. Menghapus data browser juga menghapus penanda dan unduhan. Cadangkan penanda melalui Pengaturan.</p></div>`)}
function showInstall(){dialogOpen('Pasang Ayat di HP',installGuideHTML(Boolean(deferredInstall)));dialog.dataset.panel='install';bindInstallGuide(dialog);}
async function refreshMushafDownloads(){const host=el('mushaf-download');if(!host)return;const status=await mushafStatus();if(!host.isConnected)return;const mode=status.running+"-"+(status.count===604);if(host.dataset.mode===mode&&host.querySelector("progress")){host.querySelector("progress").value=status.count;host.querySelector("[aria-live]").textContent=status.count+" / 604 halaman tersimpan · paket "+bytesLabel(status.bytes);return;}host.dataset.mode=mode;host.innerHTML=`<h3>Mushaf per halaman</h3><p>Mushaf Madinah 1441 H · 604 halaman. Halaman yang dibuka tersimpan otomatis. Unduh semuanya agar seluruh lembar tersedia tanpa internet.</p><progress value="${status.count}" max="604" aria-label="Halaman mushaf tersimpan"></progress><small aria-live="polite">${status.count} / 604 halaman tersimpan · paket ${bytesLabel(status.bytes)}</small><button class="pill" data-action="${status.running?'cancel-mushaf':'download-mushaf'}" ${status.count===604?'disabled':''}>${icon(status.running?'close':'download')}${status.running?'Jeda unduhan':status.count===604?'Seluruh mushaf siap offline':status.count>0?'Lengkapi unduhan mushaf':'Unduh mushaf lengkap'}</button>${status.error?`<p class="download-error" role="alert">${esc(status.error)}</p>`:''}<small>Biarkan aplikasi terbuka selama mengunduh. Unduhan dapat dilanjutkan jika terputus.</small>`;}
window.addEventListener('mushaf-cache-change',()=>{if(view==='downloads')refreshMushafDownloads();});

function refreshDownloadUI(){if(view==='downloads')renderDownloads();if(view==='home')renderList();const route=currentRoute();if(route&&el('reader-download')){const id=route.surah,dl=downloads.get(downloadKey(id));el('reader-download').innerHTML=`${icon(downloaded.has(id)?'check':dl?'clock':'download')}${downloaded.has(id)?'Audio tersimpan':dl?`Mengunduh ${Math.round(dl.progress*100)}%`:`Unduh · ${bytesLabel(sBy(id).audioBytes)}`}`;}}
async function downloadSurah(id,reciter=state.settings.reciter){const key=downloadKey(id,reciter);if(reciter===state.settings.reciter&&downloaded.has(id))return true;if(downloads.has(key))return false;if(!navigator.onLine){toast('Sambungkan internet untuk mengunduh audio.');return false;}const s=sBy(id),q=reciterBy(reciter);if(!s||!q)return false;const controller=new AbortController();downloads.set(key,{controller,progress:0,reciter,id});refreshDownloadUI();try{
  navigator.storage?.persist?.().catch(()=>{});const r=await fetch(audioURL(id,q.baseURL),{signal:controller.signal});if(!r.ok||!r.headers.get('content-type')?.includes('audio'))throw Error('Audio tidak dapat diunduh.');
  const size=Number(r.headers.get('content-length'))||q.chapters.find(c=>c.id===id).bytes,reader=r.body.getReader(),chunks=[];let loaded=0,last=0;
  while(true){const {done,value}=await reader.read();if(done)break;chunks.push(value);loaded+=value.length;if(Date.now()-last>400){downloads.get(key).progress=Math.min(.99,loaded/size);refreshDownloadUI();last=Date.now();}}
  if(loaded!==size)throw Error('Unduhan belum lengkap. Coba lagi.');const blob=new Blob(chunks,{type:'audio/mpeg'});await saveAudio({id,blob,bytes:blob.size,savedAt:Date.now()},reciter);if(reciter===state.settings.reciter)downloaded.add(id);toast(s.name+' · '+q.name+' siap offline.');return true;
}catch(e){toast(e.name==='AbortError'?'Unduhan dibatalkan.':e.name==='QuotaExceededError'?'Penyimpanan penuh. Hapus beberapa unduhan.':e.message||'Unduhan gagal.');return false;}finally{downloads.delete(key);refreshDownloadUI();}}
async function downloadAll(){if(batch)return;const reciter=state.settings.reciter,existing=new Set(await listAudio(reciter));batch=true;batchAbort=false;refreshDownloadUI();for(const s of surahs){if(batchAbort)break;if(!existing.has(s.id)&&!await downloadSurah(s.id,reciter))break;}batch=false;refreshDownloadUI();}
function markPlaying(){syncPlaybackButtons();document.querySelectorAll('.ayah.active,.page-ayah.active').forEach(n=>n.classList.remove('active'));if(player&&!audio.paused&&!audio.ended&&!player.loading&&!player.error)document.querySelectorAll('.ayah[data-surah="'+player.surah+'"][data-ayah="'+player.ayah+'"],.page-ayah[data-surah="'+player.surah+'"][data-ayah="'+player.ayah+'"]').forEach(n=>n.classList.add('active'));}
function juzAt(position){return data.juzs.findLast(j=>j.surah<position.surah||j.surah===position.surah&&j.ayah<=position.ayah)?.id||1;}
function syncPlaybackButtons(){
  for(const b of document.querySelectorAll('[data-action="play-ayah"],[data-action="play-scope"]')){
    const scope=b.dataset.action==='play-scope',kind=b.dataset.kind,id=Number(b.dataset.scopeId),n=Number(b.dataset.ayah);
    const same=Boolean(player&&player.reciter===state.settings.reciter&&(scope?player.continuous&&player.scope?.kind===kind&&player.scope.id===id:player.surah===Number(b.dataset.surah)&&player.ayah===n));
    const loading=same&&player.loading,playing=same&&!audio.paused&&!audio.ended&&!player.error&&!player.finished,resumable=same&&audio.paused&&!player.error&&!player.finished;
    const label=scope?(kind==='juz'?'Juz '+id:'Surah '+sBy(id).name):'ayat '+n;
    const action=loading?'Menyiapkan audio':playing?'Jeda':resumable?'Lanjutkan':'Putar';
    b.disabled=loading;b.classList.toggle('is-loading',loading);b.classList.toggle('is-playing',playing&&!loading);b.setAttribute('aria-busy',String(loading));b.setAttribute('aria-label',(b.classList.contains('reader-play-context')&&!playing&&!resumable&&!loading?'Dengarkan Audio — ':action+' ')+label+(scope&&!same?' dari awal':''));b.title=b.getAttribute('aria-label');
    const glyph=loading?'<span class="audio-button-spinner" aria-hidden="true"></span>':icon(playing?'pause':'play');
    const caption=scope?(b.classList.contains('reader-play-context')?(loading?'Memuat Audio':playing?'Jeda Audio':resumable?'Lanjutkan Audio':'Dengarkan Audio'):(loading?'Memuat…':(playing?'Jeda':resumable?'Lanjut':'Putar')+' '+label)):b.closest('.verse-actions')?(loading?'Menyiapkan audio…':playing?'Jeda ayat':resumable?'Lanjutkan ayat':'Dengarkan ayat'):'';
    b.innerHTML=glyph+(caption?'<span>'+esc(caption)+'</span>':'');
  }
}
function togglePlayback(){if(!player||player.loading)return;if(audio.paused){if(player.finished||player.error)playAyah(player.surah,player.ayah,player.continuous,player.scope);else audio.play().catch(()=>toast('Audio belum dapat diputar. Coba lagi saat online.'));}else audio.pause();}
function playScope(kind,id){const range=audioRange(data,kind,id);if(!range)return;if(player?.continuous&&player.scope?.kind===kind&&player.scope.id===id&&!player.finished&&!player.error){togglePlayback();return;}playAyah(range.start.surah,range.start.ayah,true,range);}
function finishSequence(){audio.pause();if(player)player.finished=true;renderPlayer();}
function atSequenceEnd(){return player?.scope&&player.surah===player.scope.end.surah&&player.ayah===player.scope.end.ayah;}
function followAudio(){const route=currentRoute();if(!route||!player)return;if(route.page){const page=pageForPosition(data.pages,player.surah,player.ayah);if(page!==route.page)navigate('#page/'+page+'/'+player.surah+'/'+player.ayah);else followPageVerse(document.querySelector('.page-ayah.active'));}else if(route.surah===player.surah)el('ayah-'+player.ayah)?.scrollIntoView({behavior:'smooth',block:'nearest'});else navigate(readingLink(player.surah,player.ayah,route.mode));}
function renderPlayer(){syncAudioPanel();syncPlaybackButtons();if(!player){playerEl.hidden=true;document.body.classList.remove('has-player');return;}const s=sBy(player.surah);playerEl.hidden=false;document.body.classList.add('has-player');playerEl.innerHTML=`<a class="player-info" href="${readingLink(s.id,player.ayah)}"><span class="player-disc">${icon('headphones')}</span><span><strong>${esc(s.name)} · Ayat ${player.ayah}</strong><small>${player.loading?'Menyiapkan audio…':esc(reciterBy(player.reciter).name)}${downloaded.has(s.id)?' · Offline':''}</small></span></a><div class="player-controls"><button data-action="previous" aria-label="Ayat sebelumnya">${icon('previous')}</button><button class="play-main" data-action="toggle-play" aria-label="${audio.paused?'Putar':'Jeda'}">${icon(audio.paused?'play':'pause')}</button><button data-action="next" aria-label="Ayat berikutnya">${icon('next')}</button></div><div class="player-timeline"><span id="player-time">0:00</span><input id="seek" type="range" min="0" max="1000" value="0" aria-label="Posisi audio ayat"><span id="player-length">0:00</span></div><div class="player-options"><button class="speed" data-action="speed" aria-label="Kecepatan audio">${audio.playbackRate}×</button><button class="repeat ${player.repeat?'on':''}" data-action="repeat" aria-label="Ulangi ayat" aria-pressed="${player.repeat}">${icon('repeat')}</button><button class="${player.continuous?'on':''}" data-action="continuous" aria-label="Putar ayat berurutan" aria-pressed="${player.continuous}">${icon('list')}</button><button data-action="close-player" aria-label="Tutup pemutar">${icon('close')}</button></div>`;updateTimeline();markPlaying();}
function updateTimeline(){if(!player||!el('seek'))return;const [from,to]=audioTiming(player.surah,player.ayah);const at=Math.max(0,Math.min(to-from,audio.currentTime*1000-from));el('seek').value=String(at/(to-from)*1000);el('player-time').textContent=timeLabel(at/1000);el('player-length').textContent=timeLabel((to-from)/1000);}
function waitMetadata(){if(audio.readyState>=1)return Promise.resolve();return new Promise((resolve,reject)=>{let timer;const done=()=>{clearTimeout(timer);audio.removeEventListener('loadedmetadata',success);audio.removeEventListener('error',fail)};const success=()=>{done();resolve()};const fail=()=>{done();reject(Error('Audio belum bisa dibuka. Periksa koneksi atau unduh surah dahulu.'))};audio.addEventListener('loadedmetadata',success);audio.addEventListener('error',fail);timer=setTimeout(fail,30000);});}
async function playAyah(id,n,continuous=false,scope=null){const s=sBy(id);if(!s||n<1||n>s.count)return;const token=++playSeq,repeat=player?.repeat||false;audio.pause();player={reciter:state.settings.reciter,surah:id,ayah:n,continuous,scope,repeat,loading:true,finished:false,advancing:false};renderPlayer();try{
  let saved;try{saved=await getAudio(id,player.reciter)}catch{}
  if(token!==playSeq)return;
  if(!saved&&!navigator.onLine)throw Error('Audio surah ini belum diunduh. Buka Unduhan saat online.');
  const sourceKey=`${player.reciter}:${id}:${saved?'offline':'online'}`;
  if(sourceKey!==currentSource||audio.error){if(currentObjectURL)URL.revokeObjectURL(currentObjectURL);currentObjectURL=saved?URL.createObjectURL(saved.blob):null;audio.src=currentObjectURL||audioURL(id,reciterBy(player.reciter).baseURL);currentSource=sourceKey;audio.load();}
  await waitMetadata();if(token!==playSeq)return;
  audio.currentTime=audioTiming(id,n)[0]/1000;await audio.play();if(token!==playSeq)return;player.loading=false;renderPlayer();followAudio();
}catch(e){if(token!==playSeq)return;player.loading=false;player.error=true;audio.pause();renderPlayer();toast(e.name==='NotAllowedError'?'Ketuk tombol putar untuk memulai audio.':e.message||'Audio belum dapat diputar.');}}
async function nextAyah(delta){if(!player)return;const s=sBy(player.surah),n=player.ayah+delta,next=sBy(s.id+delta);const target=n>=1&&n<=s.count?{surah:s.id,ayah:n}:next?{surah:next.id,ayah:delta>0?1:next.count}:null;if(target&&inAudioRange(player.scope,target.surah,target.ayah))return playAyah(target.surah,target.ayah,player.continuous,player.scope);if(delta>0)finishSequence();}
audio.addEventListener('timeupdate',()=>{updateTimeline();if(!player||audio.paused||player.loading||player.advancing)return;const s=sBy(player.surah),a=s.ayahs[player.ayah-1];if(audio.currentTime*1000<audioTiming(s.id,player.ayah)[1])return;if(player.repeat){audio.currentTime=audioTiming(s.id,player.ayah)[0]/1000;return;}if(player.continuous&&atSequenceEnd()){finishSequence();return;}if(player.continuous&&player.ayah<s.count){player.ayah++;renderPlayer();followAudio();return;}if(player.continuous&&s.id<114){player.advancing=true;nextAyah(1);return;}audio.pause();player.finished=true;renderPlayer();});
audio.addEventListener('ended',()=>{if(!player||player.advancing||player.finished)return;if(player.repeat)playAyah(player.surah,player.ayah,player.continuous,player.scope);else if(atSequenceEnd())finishSequence();else if(player.continuous){player.advancing=true;nextAyah(1);}else{player.finished=true;renderPlayer();}});
audio.addEventListener('play',()=>renderPlayer());audio.addEventListener('pause',()=>renderPlayer());
audio.addEventListener('error',()=>{if(player&&!player.loading){player.error=true;audio.pause();toast('Audio terhenti. Periksa koneksi atau unduh surah ini.');renderPlayer();}});

document.addEventListener('click',async event=>{
  const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=Number(b.dataset.surah),n=Number(b.dataset.ayah);
  if(!data&&action!=='close-dialog')return;
  switch(action){
    case'reader-open':goRead(id,n,currentRoute().mode);scrollTo(0,0);break;
    case'reading-mode':{const r=currentPosition();if(!r)break;state.settings.readingMode=b.dataset.mode;persist();goRead(r.surah,r.ayah);scrollTo(0,0);break;}
    case'audio-panel':showAudioPanel();break;
    case'mushaf-retry':render();break;
    case'download-mushaf':downloadMushaf();break;
    case'cancel-mushaf':cancelMushafDownload();break;
    case'mushaf-downloads':dialog.close();navigate('#downloads');break;
    case'page-picker':{const r=currentRoute();dialogOpen('Buka halaman',`<form id="page-picker-form"><label for="page-number">Nomor halaman (1–604)</label><input id="page-number" type="number" min="1" max="604" step="1" required inputmode="numeric" value="${r.page}" autofocus><button class="primary" type="submit">Buka halaman</button></form><p class="dialog-copy">Seperti membuka mushaf Arab, usap jari ke kanan untuk halaman berikutnya, atau ke kiri untuk kembali. Kamu juga bisa mengetuk tepi kertas yang kosong: kiri untuk berikutnya, kanan untuk sebelumnya.</p>`);break;}
    case'page-turn':goPage(Number(b.dataset.page));break;
    case'select-ayah':{const y=scrollY,page=currentRoute().page;selectedPageAyah={page,surah:id,ayah:n};history.replaceState(null,'','#page/'+page+'/'+id+'/'+n);render();scrollTo(0,y);showAyahActions(id,n);break;}
    case'play-sequence':playAyah(id,n,true,audioRange(data,'surah',id));break;
    case'play-scope':playScope(b.dataset.kind,Number(b.dataset.scopeId));break;
    case'translation':{const y=scrollY;state.settings.translation=!state.settings.translation;persist();render();scrollTo(0,y);if(dialog.open)showSettings();break;}
    case'continue':goRead(state.lastRead?.surah||1,state.lastRead?.ayah||1);break;
    case'settings':showSettings();break;case'sources':showSources();break;case'close-dialog':dialog.close();break;
    case'dark':state.settings.dark=!state.settings.dark;applySettings();persist();showSettings();break;
    case'latin':{const y=scrollY;state.settings.latin=!state.settings.latin;persist();render();scrollTo(0,y);if(dialog.open)showSettings();break;}
    case'tajweed':{const y=scrollY;state.settings.tajweed=!state.settings.tajweed;persist();render();scrollTo(0,y);if(dialog.open)showSettings();break;}
    case'install':showInstall();break;case'install-now':if(deferredInstall){await deferredInstall.prompt();deferredInstall=null;dialog.close();}break;
    case'bookmark':{const at=state.bookmarks.findIndex(v=>v.surah===id&&v.ayah===n);if(at>=0)state.bookmarks.splice(at,1);else state.bookmarks.push({surah:id,ayah:n,at:Date.now()});const saved=persist(),y=scrollY;render();scrollTo(0,y);if(dialog.dataset.panel==='verse')dialog.close();if(saved)toast(at>=0?'Penanda dihapus.':'Ayat disimpan di Penanda.');break;}
    case'save-position':{const cancel=state.lastRead?.surah===id&&state.lastRead.ayah===n;state.lastRead=cancel?null:{surah:id,ayah:n,at:Date.now()};const saved=persist(),y=scrollY;render();scrollTo(0,y);if(dialog.dataset.panel==='verse')dialog.close();if(saved)toast(cancel?'Posisi terakhir dibaca dibatalkan.':`Posisi tersimpan: ${sBy(id).name}, ayat ${n}.`);break;}
    case'download':await downloadSurah(id);break;
    case'cancel-download':downloads.get(downloadKey(id))?.controller.abort();break;
    case'remove-audio':try{await removeAudio(id,state.settings.reciter);downloaded.delete(id);refreshDownloadUI();toast('Audio dihapus dari perangkat.');}catch{toast('Audio belum bisa dihapus.');}break;
    case'download-all':downloadAll();break;
    case'cancel-all':batchAbort=true;downloads.forEach(v=>v.controller.abort());break;
    case'play-surah':playScope('surah',id);break;case'play-ayah':if(dialog.dataset.panel==='verse')dialog.close();if(player?.surah===id&&player.ayah===n&&player.reciter===state.settings.reciter&&!player.finished&&!player.error)togglePlayback();else playAyah(id,n,false);break;
    case'toggle-play':togglePlayback();break;
    case'next':nextAyah(1);break;case'previous':nextAyah(-1);break;
    case'repeat':if(player){player.repeat=!player.repeat;renderPlayer();}break;
    case'continuous':if(player){player.continuous=!player.continuous;renderPlayer();}break;
    case'speed':audio.playbackRate=audio.playbackRate>=1.5?.75:audio.playbackRate+.25;renderPlayer();break;
    case'close-player':stopPlayer();break;
    case'export':{const blob=new Blob([JSON.stringify({app:'ayat',version:1,...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ayat-penanda.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}
  }
});
document.addEventListener('submit',e=>{if(e.target.id==='page-picker-form'){e.preventDefault();const n=Number(el('page-number').value);if(Number.isInteger(n)&&n>=1&&n<=604){dialog.close();goPage(n);}}});
document.addEventListener('input',e=>{if(e.target.id==='header-search')updateHeaderSearch();if(e.target.id==='directory-search'){search=e.target.value;renderList();}if(e.target.id==='font-size'){state.settings.fontSize=Number(e.target.value);applySettings();el('font-label').textContent=state.settings.fontSize+' px';document.querySelector('.settings-example').style.fontSize=state.settings.fontSize+'px';persist();}if(e.target.id==='seek'&&player){const [from,to]=audioTiming(player.surah,player.ayah);audio.currentTime=(from+(to-from)*Number(e.target.value)/1000)/1000;player.finished=false;updateTimeline();}});
document.addEventListener('change',async e=>{if(e.target.matches('.reciter-select')){await changeReciter(Number(e.target.value));return;}if(e.target.id==='jump-page')goPage(Number(e.target.value));if(e.target.id==='jump-ayah'){const r=currentRoute();if(r){dialog.close();goRead(r.surah,Number(e.target.value));}}if(e.target.id==='import-file'){try{const file=e.target.files[0];if(!file||file.size>1e6)throw Error('Berkas terlalu besar.');const incoming=JSON.parse(await file.text());if(incoming.app!=='ayat'||!Array.isArray(incoming.bookmarks)||incoming.bookmarks.some(p=>!isValidPosition(p,surahs))||(incoming.lastRead&&!isValidPosition(incoming.lastRead,surahs)))throw Error('Berkas cadangan tidak valid.');const unique=new Map([...state.bookmarks,...incoming.bookmarks].map(p=>[`${p.surah}:${p.ayah}`,{surah:p.surah,ayah:p.ayah,at:p.at}]));state.bookmarks=[...unique.values()];if(incoming.lastRead)state.lastRead=incoming.lastRead;persist();render();dialog.close();toast('Penanda berhasil dipulihkan.');}catch(err){toast(err.message||'Cadangan tidak dapat dibaca.');}}});
document.addEventListener('focusin',e=>{if(e.target.id==='header-search')updateHeaderSearch();});
document.addEventListener('click',e=>{if(e.target.closest('.header-search'))updateHeaderSearch();else if(!e.target.closest('.header-search-wrap'))closeHeaderSearch();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!el('header-search-results').hidden){el('header-search').focus();closeHeaderSearch();e.preventDefault();return;}if((e.key==='Enter'||e.key===' ')&&e.target.matches('.page-ayah')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true,detail:0}));}});
dialog.addEventListener('close',()=>{if(playerEl.parentElement!==document.body)document.body.append(playerEl);dialog.dataset.panel='';});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
window.addEventListener('hashchange',()=>{closeHeaderSearch(true);selectedPageAyah=null;render();const r=currentRoute();if(!r||r.page||r.ayah===1)scrollTo(0,0);});
window.addEventListener('online',setConnection);window.addEventListener('offline',setConnection);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;});
async function setupOffline(){if(!('serviceWorker'in navigator)||!window.isSecureContext){setConnection();return;}try{
  const reg=await navigator.serviceWorker.register('./sw.js');
  const active=await navigator.serviceWorker.ready;offlineReady=Boolean(active.active);setConnection();
  reg.addEventListener('updatefound',()=>{const w=reg.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)toast('Versi baru siap. Buka ulang Ayat untuk memperbarui.');});});
}catch{setConnection();toast('Teks belum tersimpan offline. Buka ulang saat koneksi stabil.');}}
async function boot(){hydrate();applySettings();try{const r=await fetch('./data/quran.json');if(!r.ok)throw Error('Data belum tersedia');data=await r.json();const mushaf=await getMushafManifest();data.pages=mushaf.pages.map(p=>({id:p.page,...p.verses[0]}));const ir=await fetch('./data/indonesian.json');if(!ir.ok)throw Error('Bacaan latin belum tersedia');const indonesian=await ir.json();const rr=await fetch('./data/reciters.json');if(!rr.ok)throw Error('Data qari belum tersedia');reciters=(await rr.json()).reciters;if(!reciters.some(r=>r.id===state.settings.reciter))state.settings.reciter=123;surahs=data.surahs;applyReciter();for(const s of surahs){const local=indonesian.chapters.find(c=>c.id===s.id);if(!local||local.ayahs.length!==s.count)throw Error('Data latin belum lengkap');s.originalName=s.name;s.name=local.name;s.meaning=local.meaning;for(const a of s.ayahs){const entry=local.ayahs.find(v=>v.n===a.n),latin=entry?.latin;if(!latin||!entry.translation)throw Error('Bacaan latin belum lengkap');a.latin=latin;a.translation=entry.translation;}}state.bookmarks=state.bookmarks.filter(p=>isValidPosition(p,surahs));if(!isValidPosition(state.lastRead,surahs))state.lastRead=null;try{downloaded=new Set(await listAudio(state.settings.reciter))}catch{toast('Penyimpanan audio tidak tersedia di mode browser ini.');}render();if(document.activeElement===el('header-search'))updateHeaderSearch();setupOffline();}catch{main.innerHTML=`<div class="error"><h1>Ruang baca belum siap</h1><p>Periksa koneksi dan buka ulang aplikasi. Jika ini pemasangan pertama, tunggu sampai teks tersimpan sebelum memakai mode offline.</p><button class="primary" onclick="location.reload()">Coba lagi</button></div>`;}}
boot();






